#!/bin/bash set -euo pipefail # APT Toolbox for SoryOS Repository # This script provides helper functions for building and managing the SoryOS APT repository. # # Functions: #   - setup_environment: Prepare the build environment #   - build_package: Build a Debian package from source #   - add_to_repository: Add a built package to the repository #   - update_repository: Update the repository metadata #   - sign_repository: Sign the repository with GPG #   - clean_workspace: Clean temporary build files # # Usage: source ./apt-toolbox.sh # Then call the functions as needed. # # Example: #   source ./apt-toolbox.sh #   setup_environment #   build_package cosmic-comp #   add_to_repository cosmic-comp_1.0.0_amd64.deb #   update_repository #   sign_repository #   clean_workspace # # Directories: #   BUILD_DIR: Where packages are built (default: ./build) #   REPO_DIR: The APT repository root (default: .) #   POOL_DIR: The package pool (default: ./pool) #   DISTS_DIR: The distributions directory (default: ./dists) set -euo pipefail BUILD_DIR=${BUILD_DIR:-./build} REPO_DIR=${REPO_DIR:-$(pwd)} POOL_DIR=${POOL_DIR:-${REPO_DIR}/pool} DISTS_DIR=${DISTS_DIR:-${REPO_DIR}/dists} # Function to set up the build environment setup_environment() {   echo 'Setting up build environment...'   mkdir -p ${BUILD_DIR} ${POOL_DIR} ${DISTS_DIR}   # Install any required build dependencies if needed   # For example:   # sudo apt-get update   # sudo apt-get install -y debhelper devscripts fakeroot   # But note: we are in a container or CI, so we assume they are present. } # Function to build a Debian package from source # Parameters:   $1 - Package name (directory under cosmic-epoch or libcosmic, etc.)   $2 - Version (optional, if not provided will try to get from git or changelog) build_package() {   local pkg_name=$1   local version=$2   if [[ -z ${pkg_name} ]]; then     echo 'Error: Package name not provided' >&2     return 1   fi   echo 